def handle(query, state):
    import re

    dns_records = state.get('dns_records', {})
    files = state.get('files', {})

    hostname = (query.get('host') or [''])[0]

    if not hostname:
        return 200, {'Content-Type': 'text/plain'}, 'DNS Lookup Service\nUsage: ?host=<hostname>'

    # Vulnerable: the service builds a shell command string by prepending 'nslookup'
    # and then dispatches it through a naive semicolon-splitting executor.
    # An attacker can append "; cat /srv/flag.txt" to inject a second command.
    command_string = 'nslookup ' + hostname

    # Simulate shell execution by splitting on ';' and dispatching each command
    parts = command_string.split(';')

    output_lines = []
    for part in parts:
        part = part.strip()
        if not part:
            continue
        tokens = part.split()
        if not tokens:
            continue
        cmd = tokens[0]
        args = tokens[1:]

        if cmd == 'nslookup':
            if not args:
                output_lines.append('Usage: nslookup <hostname>')
            else:
                target = args[0]
                record = dns_records.get(target)
                if record:
                    output_lines.append('Server:\tns1.internal')
                    output_lines.append('Address:\t' + record)
                else:
                    output_lines.append('** server can\'t find ' + target + ': NXDOMAIN')
        elif cmd == 'cat':
            if not args:
                output_lines.append('cat: missing operand')
            else:
                path = args[0]
                content = files.get(path)
                if content is None:
                    output_lines.append('cat: ' + path + ': No such file or directory')
                else:
                    output_lines.append(content)
        elif cmd == 'echo':
            output_lines.append(' '.join(args))
        else:
            output_lines.append(cmd + ': command not found')

    body = '\n'.join(output_lines)
    return 200, {'Content-Type': 'text/plain'}, body
